const young = [
  { id: 'a', reachable: true, age: 1 },   // 2nd survival -> promote
  { id: 'b', reachable: true, age: 0 },   // 1st survival -> stay
  { id: 'c', reachable: false, age: 0 },  // dead -> abandon
  { id: 'd', reachable: true, age: 1 },   // 2nd survival -> promote
  { id: 'e', reachable: false, age: 1 },  // dead -> abandon
];

const newSpace = [];
const oldSpace = [];
let abandoned = 0;
for (const obj of young) {
  if (!obj.reachable) { abandoned++; continue; }
  if (obj.age >= 1) oldSpace.push(obj.id);
  else newSpace.push(obj.id);
}
console.log('new=' + newSpace.join(',') + ' promoted=' + oldSpace.join(',') + ' abandoned=' + abandoned);
